(()=>{'use strict';for(const card of document.querySelectorAll('article')){const video=card.querySelector('video'),input=card.querySelector('input'),status=card.querySelector('.status');let start=0,end=null;const controls=document.createElement('div');controls.hidden=true;controls.innerHTML='<p>Videoyu durdurup yalnız eylemin göründüğü bölümü seç.</p><button type="button">Başlangıcı buradan al</button> <button type="button">Bitişi buradan al</button> <button type="button">Seçilen bölümü izle</button> <button type="button">Seçimi sıfırla</button><p class="clip-range"></p>';input.closest('label').after(controls);const buttons=controls.querySelectorAll('button'),range=controls.querySelector('.clip-range');const update=()=>range.textContent=`Seçilen bölüm: ${start.toFixed(2)} – ${(end??video.duration).toFixed(2)} saniye`;buttons[0].onclick=()=>{if(end!==null&&video.currentTime>=end-.1){status.textContent='Başlangıç, bitişten önce olmalı.';return;}start=video.currentTime;update();};buttons[1].onclick=()=>{if(video.currentTime<=start+.1){status.textContent='Bitiş, başlangıçtan sonra olmalı.';return;}end=video.currentTime;update();};buttons[2].onclick=()=>{video.currentTime=start;video.play().catch(()=>status.textContent='Oynat düğmesine bas.');};buttons[3].onclick=()=>{start=0;end=null;update();};input.addEventListener('change',()=>{start=0;end=null;controls.hidden=true;video.loop=false;});video.addEventListener('loadedmetadata',()=>{video.pause();video.loop=false;controls.hidden=false;update();status.textContent='Yalnız eylemin göründüğü bölümü seç.';});const restart=()=>{if(!video.paused&&end!==null&&video.currentTime>=end)video.currentTime=start;};video.addEventListener('timeupdate',restart);video.addEventListener('ended',()=>{video.currentTime=start;video.play().catch(()=>{});});let frameId=null;const watch=()=>{restart();if(!video.paused&&video.requestVideoFrameCallback)frameId=video.requestVideoFrameCallback(watch);};video.addEventListener('play',()=>{if(video.requestVideoFrameCallback)frameId=video.requestVideoFrameCallback(watch);});video.addEventListener('pause',()=>{if(frameId!==null&&video.cancelVideoFrameCallback)video.cancelVideoFrameCallback(frameId);frameId=null;});}})();
